pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner) public {
        vm.assume(owner != address(0));
        // Make the fuzzed address the owner by exploiting that smartfix_owner is initialized to msg.sender.
        // We redeploy C with the fuzzed address as deployer so it becomes the owner.
        vm.prank(owner);
        C cOwner = new C();
        // The owner must call sudicideAnyone
        vm.prank(owner);
        cOwner.sudicideAnyone();
        // After a successful selfdestruct, the contract's code must be empty.
        // The reference selfdestructs and its code length becomes 0;
        // the mutant leaves the code intact, so its length remains > 0.
        assertTrue(address(cOwner).code.length == 0);
    }
}

