pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(actor, amount);
        vm.prank(actor);
        // Force feed ether to C so it has a non-zero balance
        (bool sent,) = payable(address(c)).call{value: amount}("");
        require(sent, "funding failed");
        // actor must be the owner to pass require
        vm.prank(actor);
        c.sudicideAnyone();
        // After selfdestruct, the contract bytecode is gone and balance is 0. Balance check on address(c) returns 0.
        assertTrue(address(c).balance == 0);
    }
}

